#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING FW_INCOMING_WAN_DMZ FW_INCOMING_DMZ_LAN FW_OUTGOING_DMZWAN FW_OUTGOING_LANDMZ; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_PORT fws_http-all && fail 'a port group named fws_http-all exists; nothing was written'
named FW_GROUP_PORT fws_web-ports && fail 'a port group named fws_web-ports exists; nothing was written'
named FW_GROUP_PORT fws_mgmt && fail 'a port group named fws_mgmt exists; nothing was written'
named FW_GROUP_IP fws_admin_hosts && fail 'an IP group named fws_admin_hosts exists; nothing was written'
named FW_GROUP_IP fws_servers && fail 'an IP group named fws_servers exists; nothing was written'
named FW_GROUP_IP fws_updates && fail 'an IP group named fws_updates exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_admin_hosts --set .COMMENT 'FWShift: admin_hosts'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.5-192.168.10.6
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.32/28
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_servers --set .COMMENT 'FWShift: servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.80
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_updates --set .COMMENT 'FWShift: updates'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_http-all --set .COMMENT 'FWShift: http-all'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_web-ports --set .COMMENT 'FWShift: web-ports'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080-8090
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_mgmt --set .COMMENT 'FWShift: mgmt'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 22
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT DropAll
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT lan_dns
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT lan_dns
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT lan_web
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_web-ports
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT lan_updates
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_updates
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT DropAll
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.10 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'allow_web+sat_web: Completes sat_web'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_http-all
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 198.51.100.0/24 --set .FROM_PORT any --set .IN_IP 203.0.113.10 --set .IN_PORT 25 --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT block_bad_mail+sat_mail
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.10 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT allow_mail+sat_mail
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.20/30 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT allow_pool+sat_pool
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_PORT" fws_web-ports
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.12 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT pol_dmz_https
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 172.16.20.0/24 --set .IN_PORT 21 --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT pol_block_ftp
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT DropAll
N=$((N+1))

# FW_INCOMING_DMZ_LAN
N=$(rows FW_INCOMING_DMZ_LAN)
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO udp --set .FROM_IP 172.16.20.0/24 --set .FROM_PORT 1024:65535 --set .IN_IP 192.168.10.50 --set .IN_PORT 514 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT syslog_fast
N=$((N+1))
gc --silent --goto FW_INCOMING_DMZ_LAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT DropAll
N=$((N+1))

# FW_OUTGOING_DMZWAN
N=$(rows FW_OUTGOING_DMZWAN)
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO tcp --set .FROM_IP 172.16.20.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT pol_dmz_out
gc --silent --set-refname "FW_OUTGOING_DMZWAN.$N.IN_PORT" fws_http-all
N=$((N+1))
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT DropAll
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT admin_mgmt
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_admin_hosts
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_servers
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_mgmt
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 172.16.20.0/24 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT lan_to_dmz
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 172.16.20.0/24 --set .IN_PORT 21 --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT pol_block_ftp
N=$((N+1))
gc --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT DropAll
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
